{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — A sound evening</title>
  <meta name="description" content="A gentle lineup of sound gatherings, private sessions, and short-form retreats. Choose your mood — let the method arrive with you.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="layout-poster">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/">Home</a>
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Private</a>
        <a href="/pricing.html">Rates</a>
        <a href="/about.html">Story</a>
        <a href="/faq.html">FAQ</a>
        <a href="/book.html">Book</a>
        <a href="/contact.html">Reach</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="title">Sound as an invitation — brief, direct, luminous.</h1>
          <p class="lead">A lean menu of sessions for the moments you want to shift. Select how you feel; the practice meets you there.</p>

          <div class="controls">
            <label for="mood">Your current mood</label>
            <select id="mood" aria-label="Choose mood">
              <option value="tethered">Tethered — restless focus</option>
              <option value="drifting">Drifting — heavy, slow</option>
              <option value="ready">Ready — curious, open</option>
            </select>

            <div class="mixer" role="radiogroup" aria-label="Sound preference">
              <button class="mix-button active" data-mix="gentle">Gentle</button>
              <button class="mix-button" data-mix="medium">Medium</button>
              <button class="mix-button" data-mix="intense">Intense</button>
            </div>
          </div>

          <div class="recommendation" id="recommendation">
            <h3>Suggested approach</h3>
            <p id="methodLine">A steady, warming session — Flowing Tides</p>
            <a id="primaryCta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <div class="hero-visual" aria-hidden="true">
          <!-- decorative SVG pattern makes visual richness without images -->
          <svg class="pattern-layer" width="320" height="320" viewBox="0 0 320 320" xmlns="http://www.w3.org/2000/svg">
            <defs>
              <pattern id="dots" width="40" height="40" patternUnits="userSpaceOnUse">
                <rect width="40" height="40" fill="none"/>
                <circle cx="4" cy="4" r="2" fill="var(--accent)" opacity="0.12" />
                <circle cx="28" cy="28" r="3" fill="var(--accent)" opacity="0.08" />
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#dots)" />
          </svg>
        </div>
      </div>
    </section>

    <!-- MYTH VS TRUTH (contradictions & disclaimers) -->
    <section class="myth-truth" id="myth_vs_truth">
      <div class="wrap">
        <h2>Myths and careful notes</h2>
        <div class="columns">
          <div>
            <h4>Myth</h4>
            <p>Sound will fix deep medical conditions by itself.</p>
          </div>
          <div>
            <h4>Truth</h4>
            <p>Sound supports relaxation, attention, and rest. It is complementary — not a replacement for medical care.</p>
          </div>
        </div>
        <p class="disclaimer">Contraindications: If you are pregnant, have epilepsy, recent head injury, uncontrolled cardiovascular conditions, or are under immediate psychiatric crisis, consult your healthcare provider before attending. Contact us at {{EMAIL}} for any questions.</p>
      </div>
    </section>

    <!-- PILLARS (programs) -->
    <section class="pillars" id="pillars">
      <div class="wrap">
        <h2>Methods we offer</h2>
        <div class="grid" id="programGrid">
          <article class="card">
            <h3 class="program-name">Flowing Tides</h3>
            <p class="desc">A short group session for easing attention and tension. 45 min.</p>
            <p class="price">Pay-what-feels-right / suggested $20</p>
          </article>

          <article class="card">
            <h3 class="program-name">Resonant Harbor</h3>
            <p class="desc">Private session focusing on breath and pitched support. 60 min.</p>
            <p class="price">Sliding scale $60–$120</p>
          </article>

          <article class="card">
            <h3 class="program-name">Deep Well — Short Series</h3>
            <p class="desc">Three concise gatherings over three weeks for a small cohort. Practical tools included.</p>
            <p class="price">Series $150 per person</p>
          </article>
        </div>
      </div>
    </section>

    <!-- CASE NOTES (testimonials) -->
    <section class="case-notes" id="case_notes">
      <div class="wrap">
        <h2>Field notes</h2>
        <blockquote>
          "A clean pause — I left with more clarity than I expected." — A local artist
        </blockquote>
        <blockquote>
          "Short, precise, and held. The sound choices fit the room." — A teacher
        </blockquote>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq" id="faq">
      <div class="wrap">
        <h2>Questions that arrive often</h2>
        <details>
          <summary>How long is a typical session?</summary>
          <p>Group gatherings run 45–60 minutes. Private sessions usually run 60 minutes. Short series are three weekly sessions.</p>
        </details>
        <details>
          <summary>What should I bring?</summary>
          <p>Comfortable clothing, a small blanket or yoga mat, and an openness to breathe. We provide bolsters if needed.</p>
        </details>
        <details>
          <summary>Are group sessions suitable for beginners?</summary>
          <p>Yes. Practices are guided and accessible. If you have medical concerns please read the contraindications above.</p>
        </details>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta" id="cta">
      <div class="wrap">
        <h2>Ready to arrive differently?</h2>
        <p>Pick a moment and we’ll meet you there.</p>
        <a id="finalCta" class="cta large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <p class="contact">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <small>&copy; <span id="year"></span> {{BUSINESS_NAME}} — local sessions in {{CITY}}, {{STATE}}</small>
      <nav class="footer-nav">
        <a href="/privacy.html">Privacy</a>
        <a href="/terms.html">Terms</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
