{"path":"assets/css/styles.css","content":"/* Minimal poetic styling for sound bath site */
:root{
  --bg:#0f1113;
  --panel:#0f1416;
  --muted:#9aa3a6;
  --accent:#8bd3c7;
  --glass:rgba(255,255,255,0.03);
  --maxwidth:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#e7efee;background:linear-gradient(180deg,var(--bg),#071013);}
.wrap{max-width:var(--maxwidth);margin:0 auto;padding:28px}
.site-header{backdrop-filter:blur(6px);background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-bottom:1px solid rgba(255,255,255,0.03)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{color:var(--accent);font-weight:600;text-decoration:none}
.main-nav a{color:var(--muted);margin-left:18px;text-decoration:none;font-size:14px}
.hero{padding:48px 0;background-image:url('/assets/img/pattern.svg');background-size:600px;background-position:80% 20%;}
.hero-inner{display:flex;gap:24px;align-items:center}
.hero-copy{flex:1;min-width:280px}
.title{margin:0 0 12px 0;font-size:32px;line-height:1.05;color:#fff}
.lead{color:var(--muted);margin:0 0 18px 0}
.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-bottom:18px}
select{padding:10px;border-radius:8px;background:var(--panel);border:1px solid rgba(255,255,255,0.04);color:#dfeef0}
.mixer{display:flex;gap:6px}
.mix-button{padding:8px 12px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:var(--muted);cursor:pointer}
.mix-button.active{background:var(--accent);color:#042726}
.recommendation{margin-top:8px;background:var(--glass);padding:14px;border-radius:10px;border:1px solid rgba(255,255,255,0.03);max-width:420px}
.recommendation h3{margin:0 0 8px 0;font-size:13px;color:var(--muted)}
.recommendation p{margin:0 0 10px 0;font-size:18px}
.cta{display:inline-block;padding:10px 16px;background:var(--accent);color:#042726;border-radius:8px;text-decoration:none;font-weight:600}
.hero-visual{width:320px;height:220px;display:flex;align-items:center;justify-content:center}
.pattern-layer{width:100%;height:100%}
.myth-truth,.pillars,.case-notes,.faq,.cta{padding:36px 0}
.myth-truth h2,.pillars h2,.case-notes h2,.faq h2,.cta h2{margin:0 0 12px 0}
.columns{display:flex;gap:18px}
.columns > div{flex:1}
.disclaimer{margin-top:12px;color:#f4b6b9;font-size:13px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-top:18px}
.card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:10px;border:1px solid rgba(255,255,255,0.03)}
.program-name{margin:0;font-size:16px}
.price{margin-top:8px;color:var(--muted)}
.case-notes blockquote{margin:12px 0;padding-left:12px;border-left:2px solid rgba(255,255,255,0.03);color:var(--muted)}
.faq details{background:var(--panel);padding:12px;border-radius:8px;margin-bottom:8px}
.cta.large{padding:14px 22px;font-size:16px}
.site-footer{border-top:1px solid rgba(255,255,255,0.03);padding:14px 0;color:var(--muted)}n
@media (max-width:800px){
  .hero-inner{flex-direction:column}
  .hero-visual{width:100%;height:140px}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // State mapping
  const methods = {
    tethered: {
      gentle:{name:'Grounding Pulse',line:'Short anchoring sounds to steady the nervous system'},
      medium:{name:'Harmonic Flow',line:'Even pulses with room to notice and re-set'},
      intense:{name:'Focused Resonance',line:'Directed tones to shift tightness and agitation'}
    },
    drifting: {
      gentle:{name:'Slow Drift',line:'Soft sustained tones to ease heaviness'},
      medium:{name:'Layered Lull',line:'Overlapping textures that renew energy quietly'},
      intense:{name:'Deep Harbor',line:'Denser waves, shorter form — practical softening'}
    },
    ready: {
      gentle:{name:'Quiet Invitation',line:'A simple introduction to sound and breath together'},
      medium:{name:'Responsive Weave',line:'Interactive cues and gentle phrasing for exploration'},
      intense:{name:'Brisk Sutra',line:'Short, potent sequences for clear transitions'}
    }
  };

  const moodSelect = document.getElementById('mood');
  const mixButtons = Array.from(document.querySelectorAll('.mix-button'));
  const methodLine = document.getElementById('methodLine');
  const primaryCta = document.getElementById('primaryCta');
  const finalCta = document.getElementById('finalCta');
  const programGrid = document.getElementById('programGrid');
  const yearSpan = document.getElementById('year');

  yearSpan.textContent = new Date().getFullYear();

  let currentMix = 'gentle';

  function updateRecommendation(){
    const mood = moodSelect.value;
    const choice = methods[mood][currentMix];
    methodLine.textContent = `${choice.name} — ${choice.line}`;

    // Update CTA phrasing based on method intensity and mood
    let ctaText = (currentMix==='gentle')? 'Reserve a calm seat' : (currentMix==='medium')? 'Claim a balanced spot' : 'Book an anchored session';

    // Slight variation by mood
    if(mood==='tethered') ctaText = ctaText.replace('seat','spot').replace('spot','place');
    if(mood==='drifting') ctaText = ctaText.replace('Claim','Hold').replace('Book','Secure');

    primaryCta.textContent = ctaText;
    finalCta.textContent = ctaText;

    // Update visible program cards to reflect we suggest a highlighted program
    Array.from(programGrid.querySelectorAll('.card')).forEach((card, idx) => {
      const nameEl = card.querySelector('.program-name');
      const desc = card.querySelector('.desc');
      const price = card.querySelector('.price');

      // Tweak copy depending on mix
      if(idx===0){
        nameEl.textContent = choice.name;
        desc.textContent = choice.line + ' — group session.';
        price.textContent = (currentMix==='intense')? 'Suggested $25 — small group' : (currentMix==='medium')? 'Suggested $20' : 'Pay-what-feels-right';
      }
      if(idx===1){
        // Private offering
        const priv = (currentMix==='gentle')? 'breath-forward' : (currentMix==='medium')? 'pitch-and-breath' : 'focused-tone work';
        nameEl.textContent = (currentMix==='intense')? 'Resonant Harbor' : 'Resonant Harbor';
        desc.textContent = `Private ${priv} session — tailored support.`;
        price.textContent = (currentMix==='intense')? 'Sliding scale $80–$160' : 'Sliding scale $60–$120';
      }
      if(idx===2){
        nameEl.textContent = (currentMix==='intense')? 'Deep Well — Short Series' : 'Deep Well — Short Series';
        desc.textContent = 'Three brief gatherings; practice and tools for the week.';
        price.textContent = (currentMix==='intense')? 'Series $180' : 'Series $150';
      }
    });
  }

  // Mixer buttons
  mixButtons.forEach(btn=>{
    btn.addEventListener('click',()=>{
      mixButtons.forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      currentMix = btn.getAttribute('data-mix');
      updateRecommendation();
    });
  });

  // Mood change
  moodSelect.addEventListener('change',updateRecommendation);

  // Initial refine: set default
  updateRecommendation();

  // Enhance CTA click to add query params that reflect mood+mix (local demo without server)
  function attachCta(cta){
    cta.addEventListener('click',function(e){
      const url = new URL(cta.getAttribute('href'),window.location.origin);
      url.searchParams.set('mood',moodSelect.value);
      url.searchParams.set('mix',currentMix);
      cta.setAttribute('href',url.toString());
      // allow normal navigation
    });
  }
  attachCta(primaryCta);
  attachCta(finalCta);

})();"} 
